export async function loadPageDocument(page,mapping,html,document,repository){const boot=await bootstrapPage(page.path,mapping,html,document),saved=await repository.load(boot.record.document_key);boot.sourceBody=structuredClone(boot.record.draft.body);if(saved){if(saved.source_hash!==boot.record.source_hash)throw Error('Canonical page changed. Private draft retained; source reconciliation is required.');boot.record=saved;boot.descriptor.id=saved.id;}return boot;}
export function createPageAdapter(){return {async create(page,presentation,options){const boot=page.document,authority={record:boot.record,registry:pageBlockRegistry,initialise:()=>boot.baseline,validate:(...args)=>{const doc=validatePageComposition(...args);for(const [id,binding] of Object.entries(boot.bindings)){const section=doc.sections.find(s=>s.blocks[id]),b=section?.blocks[id];if(!b||b.type!==binding.initial.type||b.version!==1)throw Error('Native binding cannot be replaced or removed.');if(binding.initial.type==='text'&&semanticNode(b,args[1]).type!=='paragraph')throw Error('Bound native fields retain their original element. Use inline text and marks.');if(binding.isProtected){if(canonical(b)!==canonical(binding.initial))throw Error('Protected application binding cannot change.');for(const l of Object.values(section.layouts))if(!l.placements[id].value.locked||!l.placements[id].value.visible)throw Error('Protected application remains visible and locked.');}}return doc;},media:async()=>[boot.assets,boot.usage],approvedImage:(b,id,assets,usage)=>{const asset=assets.find(a=>a.id===b.content.assetId),reference=usage.find(u=>u.block_ref===b.content.usageRef&&u.asset_id===b.content.assetId);if(!asset||!reference)throw Error('Image requires approved document media.');return {asset,reference};},save:(record,draft,manifest)=>options.documentRepository.save({...record,draft,manifest}),saved:row=>{boot.record=row;},surface:args=>nativeSurface({...args,bindings:boot.bindings,baseline:boot.baseline}),configureTextEditor:(editor,element,b)=>{if(!boot.bindings[b.id])return;element.querySelectorAll('[data-editor-command]').forEach(control=>{if(!['Bold','Italic','Link','Undo','Redo'].includes(control.dataset.editorCommand))control.hidden=true;});},renderBlock:(el,b,body)=>{const binding=boot.bindings[b.id];if(!binding)return false;if(binding.isProtected)return true;if(b.type==='text'){const current=semanticNode(b,body),original=semanticNode(binding.initial,boot.initialBody);if(canonical(current.content||[])===canonical(original.content||[]))el.innerHTML=binding.original;else{el.innerHTML=renderBody({type:'doc',content:[current]},boot.presentation,b.content.slot);const paragraph=el.firstElementChild;if(paragraph?.tagName==='P')paragraph.replaceWith(...paragraph.childNodes);}return true;}if(b.type==='button'){el.textContent=b.content.label;const node=el.ownerDocument.querySelector('[data-block="'+b.id+'"]');if(node?.tagName==='A')node.setAttribute('href',b.content.href);return true;}if(b.type==='image'&&binding.tag==='DIV'){const node=el.ownerDocument.querySelector('[data-block="'+b.id+'"]'),asset=boot.assets.find(a=>a.id===b.content.assetId);if(node){if(canonical(b.content)!==canonical(binding.initial.content))node.style.backgroundImage='url("'+asset.path+'")';if(b.presentation.fit!==binding.initial.presentation.fit)node.style.backgroundSize=b.presentation.fit;}return true;}return false;}};boot.initialBody=structuredClone(boot.record.edit_version?boot.sourceBody:boot.record.draft.body);return createDocumentSession(page,presentation,options,authority);}};}
